/* Official provider sites for the big delivery channels (well-known domains; still verify the program page). Everything else gets an official-site search link — no invented URLs. */
const DPR_SITES=[["California Housing Finance Agency (CalHFA)","https://www.calhfa.ca.gov"],["CalVet Home Loans","https://www.calvet.ca.gov/HomeLoans"],["Golden State Finance Authority (GSFA)","https://www.gsfahome.org"],["MOHCD San Francisco","https://sf.gov/departments/mayors-office-housing-and-community-development"],["Los Angeles County Development Authority (LACDA)","https://www.lacda.org"],["City of Los Angeles (LAHD)","https://housing.lacity.gov"],["San Diego Housing Commission (SDHC)","https://www.sdhc.org"],["Federal Home Loan Bank (FHLB) of San Francisco","https://www.fhlbsf.com"],["CBC Mortgage Chenoa Fund","https://chenoafund.org"],["National Homebuyers Fund (NHF)","https://www.nhfloan.org"],["HUD Good Neighbor Next Door","https://www.hud.gov/program_offices/housing/sfh/reo/goodn/gnndabot"],["United States Department of Veterans Affairs - Specially Adapted Housing","https://www.va.gov/housing-assistance/disability-housing-grants"],["Neighborhood Partnership Housing Services (NPHS)","https://nphsinc.org"],["Neighborhood Housing Services of the Inland Empire (NHSIE)","https://www.nhsie.org"],["Housing Trust of Silicon Valley","https://housingtrustsv.org"],["Housing Trust Fund of Santa Barbara County","https://www.sbhousingtrust.org"],["Self-Help Enterprises (SHE)","https://www.selfhelpenterprises.org"],["Habitat for Humanity of Greater Los Angeles","https://www.habitatla.org"],["Los Angeles Neighborhood Housing Services (NHSLA)","https://www.nhslacounty.org"],["NeighborWorks of Orange County","https://www.nwoc.org"],["Sacramento Housing and Redevelopment Agency (SHRA)","https://www.shra.org"],["Riverside County","https://rivcohws.org"],["Orange County Mortgage Assistance Program","https://www.ochousing.org"],["Community Housing Development Corporation (CHDC)","https://www.chdcnr.org"],["Down Payment Resource (DPR) directory","https://downpaymentresource.com"]];
const DPR_BASIS={P:"% of purchase price",TL:"% of total loan amount",C:"% of cost / combined",V:"% of value",BL:"% of base loan",'':"flat $ or see program"};
const DPR_TYPE_NOTES={"2nd Mortgage":"Silent/deferred or amortizing second lien; check forgiveness, due-on-sale, shared appreciation and resale restrictions. Subordination letter must be in the file before docs.","Combined Assistance":"First mortgage + DPA second/grant delivered through participating lenders (CalHFA, GSFA, Chenoa, wholesale DPAs). Usually FHA/conventional; VA buyers rarely need these except closing-cost help.","Grant":"No repayment; often tied to a specific lender, employer, REALTOR® association or tribe. Document the grant letter and the funds transfer.","BMR / Resale Restriction":"Below-market-rate units with deed restrictions and resale caps; lenders need the restriction reviewed — VA and FHA allow many of them with conditions.","Deed Restriction":"Inclusionary units; price and buyer restrictions recorded against title.","1st Mortgage":"A first-lien product (CalHFA, CalVet QVMB, UC MOP) — compare against VA pricing before recommending.","Housing Choice Voucher":"Section 8 homeownership — the voucher pays part of PITI; servicer must accept it.","Matched Savings Program":"IDA/WISH: the agency matches the buyer's savings (often 3:1 or 4:1) up to the cap; lead time of months.","Mortgage Credit Certificate":"Federal tax credit on mortgage interest — lender adds the credit to qualifying income.","Rehab Assistance":"Repair/renovation funds; pairs with VA alteration & repair or 203(k).","Other Homebuyer Assistance":"Family Self-Sufficiency escrow and similar."};
function dprSite(name){const hit=DPR_SITES.find(s=>name.toLowerCase().includes(s[0].toLowerCase().split(" (")[0].toLowerCase()));return hit?hit[1]:null}
